  1	import { describe, it, expect, beforeEach, afterEach } from 'vitest';
  2	import { mkdtemp, rm, mkdir, writeFile } from 'fs/promises';
  3	import { join } from 'path';
  4	import { tmpdir } from 'os';
  5	import { LedgerStore } from '../../src/storage/ledger-store.js';
  6	import { atomicWriteJson } from '../../src/storage/atomic-writer.js';
  7	import type { RootIndex } from '../../src/schema/root-index.js';
  8	import { now } from '../../src/utils/timestamp.js';
  9	
 10	// Fixed plan path with valid YYYY-MM-DD slug; tempLedgerRoot is used as the ledger root.
 11	const PLAN_PATH = join(tmpdir(), '2026-01-15-meta-test');
 12	
 13	function makeRootIndex(overrides: Partial<RootIndex> = {}): RootIndex {
 14	  return {
 15	    plan_file: 'plan.md',
 16	    date_created: now(),
 17	    last_updated: now(),
 18	    status: 'IN_PROGRESS',
 19	    total_work_packages: 0,
 20	    pending_work_packages: 0,
 21	    work_packages: [],
 22	    project_comments: [],
 23	    ...overrides,
 24	  };
 25	}
 26	
 27	describe('ProjectMeta — writeProjectMeta / readProjectMeta', () => {
 28	  let tempLedgerRoot: string;
 29	  let store: LedgerStore;
 30	
 31	  beforeEach(async () => {
 32	    tempLedgerRoot = await mkdtemp(join(tmpdir(), 'meta-test-'));
 33	    store = new LedgerStore(PLAN_PATH, tempLedgerRoot);
 34	  });
 35	
 36	  afterEach(async () => {
 37	    await rm(tempLedgerRoot, { recursive: true, force: true });
 38	  });
 39	
 40	  it('writeProjectMeta creates a valid .meta.json with correct fields on first write', async () => {
 41	    await store.writeProjectMeta('plan.md', 'IN_PROGRESS');
 42	
 43	    const meta = await store.readProjectMeta();
 44	    expect(meta.slug).toBe('2026-01-15-meta-test');
 45	    expect(meta.plan_path).toBe(PLAN_PATH);
 46	    expect(meta.status).toBe('IN_PROGRESS');
 47	    expect(typeof meta.date_created).toBe('string');
 48	    expect(typeof meta.last_updated).toBe('string');
 49	  });
 50	
 51	  it('writeProjectMeta updates status and last_updated on subsequent call', async () => {
 52	    await store.writeProjectMeta('plan.md', 'IN_PROGRESS');
 53	    const first = await store.readProjectMeta();
 54	
 55	    // Small delay ensures timestamps differ
 56	    await new Promise((r) => setTimeout(r, 10));
 57	
 58	    await store.writeProjectMeta('', 'COMPLETE');
 59	    const second = await store.readProjectMeta();
 60	
 61	    expect(second.status).toBe('COMPLETE');
 62	    expect(second.date_created).toBe(first.date_created); // preserved
 63	    expect(second.slug).toBe(first.slug);                 // preserved
 64	    expect(second.plan_path).toBe(first.plan_path);       // preserved
 65	  });
 66	
 67	  it('readProjectMeta returns validated ProjectMeta', async () => {
 68	    await store.writeProjectMeta('plan.md', 'READY');
 69	    const meta = await store.readProjectMeta();
 70	
 71	    expect(meta).toMatchObject({
 72	      slug: '2026-01-15-meta-test',
 73	      plan_path: PLAN_PATH,
 74	      status: 'READY',
 75	    });
 76	    expect(meta.date_created).toMatch(/\d{4}-\d{2}-\d{2}/);
 77	    expect(meta.last_updated).toMatch(/\d{4}-\d{2}-\d{2}/);
 78	  });
 79	
 80	  it('readProjectMeta throws when .meta.json is missing', async () => {
 81	    await expect(store.readProjectMeta()).rejects.toThrow('Project meta not found');
 82	  });
 83	
 84	  it('readProjectMeta throws on malformed JSON', async () => {
 85	    await mkdir(store.storageDir, { recursive: true });
 86	    await writeFile(store.metaPath(), '{ bad json ???', 'utf-8');
 87	    await expect(store.readProjectMeta()).rejects.toThrow('Malformed JSON');
 88	  });
 89	
 90	  it('readProjectMeta throws on schema validation failure', async () => {
 91	    await mkdir(store.storageDir, { recursive: true });
 92	    await atomicWriteJson(store.metaPath(), { slug: 'x', status: 'INVALID_STATUS' });
 93	    await expect(store.readProjectMeta()).rejects.toThrow('validation failed');
 94	  });
 95	
 96	  it('writeRootIndex auto-syncs .meta.json', async () => {
 97	    await store.writeRootIndex(makeRootIndex({ status: 'READY' }));
 98	    const meta = await store.readProjectMeta();
 99	    expect(meta.slug).toBe('2026-01-15-meta-test');
100	    expect(meta.status).toBe('READY');

101	  });
102	
103	  it('writeProjectMeta with outcome_summary persists and readProjectMeta returns it unchanged', async () => {
104	    await store.writeProjectMeta('plan.md', 'COMPLETE', {
105	      outcome_summary: 'Project delivered X via Y with result Z.',
106	    });
107	
108	    const meta = await store.readProjectMeta();
109	    expect(meta.outcome_summary).toBe('Project delivered X via Y with result Z.');
110	    expect(meta.status).toBe('COMPLETE');
111	  });
112	
113	  it('updateWorkPackageWithSync auto-syncs .meta.json status', async () => {
114	    await store.writeRootIndex(makeRootIndex({
115	      status: 'IN_PROGRESS',
116	      total_work_packages: 1,
117	      pending_work_packages: 1,
118	      work_packages: [{
119	        work_package_id: 'WP-001',
120	        status: 'IN_PROGRESS',
121	        assigned_to: 'Developer',
122	        dependencies: [],
123	        file: 'ledger/WP-001.json',
124	      }],
125	    }));
126	    await store.writeWorkPackage('WP-001', {
127	      work_package_id: 'WP-001',
128	      work_package_file: 'work/WP-001.md',
129	      status: 'IN_PROGRESS',
130	      assigned_to: 'Developer',
131	      dependencies: [],
132	      acceptance_criteria: [],
133	      revision: 0,
134	      pipelines: [],
135	    });
136	
137	    await store.updateWorkPackageWithSync('WP-001', (wp, root) => {
138	      wp.status = 'COMPLETE';
139	      root.status = 'COMPLETE';
140	      root.pending_work_packages = 0;
141	      const summary = root.work_packages.find((s) => s.work_package_id === 'WP-001');
142	      if (summary) summary.status = 'COMPLETE';
143	      return { wp, root };
144	    });
145	
146	    const meta = await store.readProjectMeta();
147	    expect(meta.status).toBe('COMPLETE');
148	  });
149	});
150	
