152	  let tempLedgerRoot: string;
153	
154	  beforeEach(async () => {
155	    tempLedgerRoot = await mkdtemp(join(tmpdir(), 'list-projects-'));
156	  });
157	
158	  afterEach(async () => {
159	    await rm(tempLedgerRoot, { recursive: true, force: true });
160	  });
161	
162	  async function createProjectMeta(
163	    slug: string,
164	    status: 'READY' | 'IN_PROGRESS' | 'COMPLETE' | 'BLOCKED'
165	  ): Promise<void> {
166	    const projectDir = join(tempLedgerRoot, slug);
167	    await mkdir(projectDir, { recursive: true });
168	    await atomicWriteJson(join(projectDir, '.meta.json'), {
169	      slug,
170	      plan_path: join('/tmp', slug),
171	      status,
172	      date_created: now(),
173	      last_updated: now(),
174	    });
175	  }
176	
177	  it('returns all projects from multiple subdirectories', async () => {
178	    await createProjectMeta('2026-01-01-project-a', 'IN_PROGRESS');
179	    await createProjectMeta('2026-02-01-project-b', 'READY');
180	    await createProjectMeta('2026-03-01-project-c', 'COMPLETE');
181	
182	    const projects = await LedgerStore.listAllProjects(tempLedgerRoot);
183	    expect(projects).toHaveLength(3);
184	    const slugs = projects.map((p) => p.slug).sort();
185	    expect(slugs).toEqual([
186	      '2026-01-01-project-a',
187	      '2026-02-01-project-b',
188	      '2026-03-01-project-c',
189	    ]);
